function NeumorphicButton({ children, onPress, style }: any) {
  const scale = React.useRef(new Animated.Value(1)).current;
  const shadow = React.useRef(new Animated.Value(8)).current;

  const handlePressIn = () => {
    Animated.parallel([
      Animated.spring(scale, {
        toValue: 0.97,
        useNativeDriver: true,
        speed: 50,
        bounciness: 0,
      }),
      Animated.timing(shadow, {
        toValue: 2,
        duration: 80,
        useNativeDriver: false,
      }),
    ]).start();
  };

  const handlePressOut = () => {
    Animated.parallel([
      Animated.spring(scale, {
        toValue: 1,
        useNativeDriver: true,
        speed: 50,
        bounciness: 8,
      }),
      Animated.timing(shadow, {
        toValue: 8,
        duration: 120,
        useNativeDriver: false,
      }),
    ]).start();
  };

  return (
    <TouchableWithoutFeedback
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      onPress={onPress}
    >
      <Animated.View
        style={[
          {
            transform: [{ scale }],
          },
          estilos.neumorphicOuter,
          style,
        ]}
      >
        <View style={estilos.neumorphicInner}>{children}</View>
      </Animated.View>
    </TouchableWithoutFeedback>
  );
}

function NeumorphicField({ children, style }: any) {
  return (
    <View style={[estilos.neumorphicOuter, style]}>
      <View style={estilos.neumorphicInner}>{children}</View>
    </View>
  );
}

export default function TelaInicio(): JSX.Element {
  const navegacao = useNavigation<NavegacaoPrincipal>();
  const { width } = useWindowDimensions();

  const [nomeUsuario, setNomeUsuario] = useState('');
  const [fotoUri, setFotoUri] = useState<string | null>(null);
  const [onlineUids, setOnlineUids] = useState<string[]>([]);
  const [fotosPorUid, setFotosPorUid] = useState<{ [uid: string]: string }>({});
  const [novaEscalaCount, setNovaEscalaCount] = useState<number>(0);
  const blinkOpacity = React.useRef(new Animated.Value(1)).current;
  const prevNovaCount = React.useRef<number>(0);
  const [novaRepertorioCount, setNovaRepertorioCount] = useState<number>(0);
  const blinkOpacityRep = React.useRef(new Animated.Value(1)).current;
  const prevNovaRepCount = React.useRef<number>(0);

  useEffect(() => {
    async function carregarDados() {
      const nome = await AsyncStorage.getItem('nomeUsuario');
      const foto = await AsyncStorage.getItem('fotoUsuario');
      if (nome) setNomeUsuario(nome);
      if (foto) setFotoUri(foto);
    }
    carregarDados();
  }, []);

  // lê flag local de nova escala quando a tela ganha foco
  useFocusEffect(
    React.useCallback(() => {
      let mounted = true;
      const lerFlag = async () => {
        try {
          const v = await AsyncStorage.getItem('nova_escala');
          if (!mounted) return;
          const n = v ? parseInt(v, 10) || 0 : 0;
          setNovaEscalaCount(n);
        } catch (e) {
          console.log('Erro ao ler flag nova_escala', e);
        }
      };
      lerFlag();
      return () => { mounted = false; };
    }, [])
  );

  useEffect(() => {
    AsyncStorage.setItem('nomeUsuario', nomeUsuario);
  }, [nomeUsuario]);

  useEffect(() => {
    if (fotoUri) {
      AsyncStorage.setItem('fotoUsuario', fotoUri);
    }
  }, [fotoUri]);

  useEffect(() => {
    const user = getAuth().currentUser;
    if (!user) return;
    const userStatusRef = ref(database, 'status/' + user.uid);

    dbSet(userStatusRef, 'online');
    onDisconnect(userStatusRef).set('offline');

    return () => {
      dbSet(userStatusRef, 'offline');
    };
  }, []);

  // Busca os UIDs online
  useEffect(() => {
    const statusRef = ref(database, 'status');
    const unsubscribe = onValue(statusRef, (snapshot) => {
      const uids: string[] = [];
      snapshot.forEach(child => {
        if (child.val() === 'online') {
          uids.push(child.key as string);
        }
      });
      setOnlineUids(uids);
    });
    return () => unsubscribe();
  }, []);

  // Busca as fotos dos usuários no Firestore
  useEffect(() => {
    async function buscarFotosUsuarios() {
      const presencaSnap = await getDocs(collection(db, 'presencas'));
      if (!presencaSnap.empty) {
        const presencaDoc = presencaSnap.docs[0];
        const fotosUsuarios = presencaDoc.data().fotosUsuarios || {};
        const fotos: { [uid: string]: string } = {};
        Object.entries(UID_TO_NOME).forEach(([uid, nome]) => {
          if (fotosUsuarios[nome]) {
            fotos[uid] = fotosUsuarios[nome];
          }
        });
        setFotosPorUid(fotos);
      }
    }
    buscarFotosUsuarios();

    // escuta contador remoto de novas escalas
    const metaRef = doc(db, 'meta', 'escalas');
    const unsub = onSnapshot(metaRef, snapshot => {
      const data = snapshot.data();
      const count = data?.newCount ? Number(data.newCount) : 0;
      setNovaEscalaCount(count);
      // atualiza badge do app para manter sincronizado
      try {
        Notifications.setBadgeCountAsync(count);
      } catch (e) {
        // não bloqueia
        console.log('Erro setando badge pelo listener', e);
      }
    }, err => {
      // se não existir o doc ou erro, mantém contador local
      console.log('Erro listener meta/escalas', err);
    });

    // escuta contador remoto de novos repertorios
    const metaRepRef = doc(db, 'meta', 'repertorios');
    const unsubRep = onSnapshot(metaRepRef, snapshot => {
      const data = snapshot.data();
      const count = data?.newCount ? Number(data.newCount) : 0;
      setNovaRepertorioCount(count);
      try {
        // optionally update app badge; keep as best-effort
        // here we don't override the global badge with rep count alone
      } catch (e) {
        console.log('Erro listener meta/repertorios badge', e);
      }
    }, err => {
      console.log('Erro listener meta/repertorios', err);
    });

    return () => { unsub(); unsubRep(); };
  }, []);

  useEffect(() => {
    const prev = prevNovaCount.current;
    if (novaEscalaCount > prev) {
      const anim = Animated.loop(
        Animated.sequence([
          Animated.timing(blinkOpacity, { toValue: 0, duration: 450, useNativeDriver: true }),
          Animated.timing(blinkOpacity, { toValue: 1, duration: 450, useNativeDriver: true }),
        ]),
        { iterations: 5 }
      );
      anim.start();
    }
    prevNovaCount.current = novaEscalaCount;
    return () => { /* noop */ };
  }, [novaEscalaCount]);

  useEffect(() => {
    const prev = prevNovaRepCount.current;
    if (novaRepertorioCount > prev) {
      const anim = Animated.loop(
        Animated.sequence([
          Animated.timing(blinkOpacityRep, { toValue: 0, duration: 450, useNativeDriver: true }),
          Animated.timing(blinkOpacityRep, { toValue: 1, duration: 450, useNativeDriver: true }),
        ]),
        { iterations: 5 }
      );
      anim.start();
    }
    prevNovaRepCount.current = novaRepertorioCount;
    return () => { /* noop */ };
  }, [novaRepertorioCount]);

  async function escolherFoto() {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.7,
    });
    if (!result.canceled && result.assets && result.assets.length > 0) {
      setFotoUri(result.assets[0].uri);
    }
  }

  function irPara<T extends keyof ListaRotasPrincipais>(
    rota: T,
    params?: ListaRotasPrincipais[T]
  ) {
    if (params !== undefined) {
      // @ts-expect-error
      navegacao.navigate(rota, params);
    } else {
      // @ts-expect-error
      navegacao.navigate(rota);
    }
  }

  async function deslogar() {
    try {
      await signOut(getAuth());
      navegacao.reset({
        index: 0,
        routes: [{ name: 'Login' as any }],
      });
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível sair da conta.');
    }
  }

  const cardWidth = (width * 0.98 - 40) / 2;

  return (
    <>
      <StatusBar
        translucent
        backgroundColor="transparent"
        barStyle="light-content"
      />
      <LinearGradient
        colors={BUTTON_GRADIENT}
        start={{ x: 0, y: 0 }}
        end={{ x: 0, y: 1 }}
        style={estilos.fundo}
      >
        <SafeAreaView style={{ flex: 1, backgroundColor: 'transparent' }}>
          <ScrollView contentContainerStyle={estilos.scrollContainer}>
            <View style={estilos.sombra}>
              <View style={{ height: 32 }} />
              {/* Perfil com destaque */}
              <View style={estilos.perfilContainer}>
                <TouchableWithoutFeedback onPress={escolherFoto}>
                  <View style={estilos.fotoPerfilNeumorphic}>
                    <LinearGradient
                      colors={['#ff9800', '#ff6f00', '#e65100']} // Gradiente laranja
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 1 }}
                      style={estilos.fotoBordaNeumorphic}
                    >
                      {fotoUri ? (
                        <Image source={{ uri: fotoUri }} style={estilos.fotoPerfil} />
                      ) : (
                        <View style={[estilos.fotoPerfil, estilos.fotoPlaceholder]}>
                          <Svg width={48} height={48} viewBox="0 0 48 48">
                            <Circle cx="24" cy="18" r="10" fill="#44474d" />
                            <Rect x="8" y="32" width="32" height="12" rx="6" fill="#44474d" />
                          </Svg>
                        </View>
                      )}
                      <View style={estilos.editarFotoIcon}>
                        <LinearGradient
                          colors={['#ff9800', '#ff6f00']} // Gradiente no ícone também
                          start={{ x: 0, y: 0 }}
                          end={{ x: 1, y: 1 }}
                          style={estilos.editarFotoIconGradient}
                        >
                          <Svg width={18} height={18} viewBox="0 0 24 24">
                            <Path d="M3 17.25V21h3.75l11.06-11.06-3.75-3.75L3 17.25z" fill="#fff"/>
                            <Path d="M20.71 7.04a1 1 0 0 0 0-1.41l-2.34-2.34a1 1 0 0 0-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z" fill="#fff"/>
                          </Svg>
                        </LinearGradient>
                      </View>
                    </LinearGradient>
                  </View>
                </TouchableWithoutFeedback>
                <Text style={estilos.saudacao}>
                  {nomeUsuario ? `Olá, ${nomeUsuario}!` : 'Bem-vindo!'}
                </Text>
                <NeumorphicField style={estilos.inputContainer}>
                  <TextInput
                    style={estilos.inputNome}
                    placeholder="Seu nome"
                    value={nomeUsuario}
                    onChangeText={setNomeUsuario}
                    placeholderTextColor="#bbb"
                    multiline={false}
                    numberOfLines={1}
                  />
                </NeumorphicField>
                <NeumorphicButton style={estilos.botaoSair} onPress={deslogar}>
                  <LinearGradient
                    colors={['#18152a', '#181a3a']}  
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={estilos.sairGradient}
                  >
                    <Feather name="log-out" size={22} color="#fff" style={{ marginRight: 8 }} />
                    <Text style={estilos.textoBotaoSair}>Sair</Text>
                  </LinearGradient>
                </NeumorphicButton>
              </View>
              {/* EXIBE USUÁRIOS ONLINE COM FOTO */}
              <View style={{ alignItems: 'center', marginBottom: 8 }}>
                <Text style={{ color: '#2ecc40', fontWeight: 'bold', marginBottom: 2 }}>Online:</Text>
                <View style={{ flexDirection: 'row', justifyContent: 'center', alignItems: 'center' }}>
                  {onlineUids.length > 0 ? (
                    onlineUids.map(uid => (
                      <View key={uid} style={{ marginHorizontal: 2 }}>
                        {fotosPorUid[uid] ? (
                          <Image
                            source={{ uri: fotosPorUid[uid] }}
                            style={{
                              width: 32,
                              height: 32,
                              borderRadius: 16,
                              borderWidth: 2,
                              borderColor: '#2ecc40',
                              backgroundColor: '#23243a',
                            }}
                          />
                        ) : (
                          <MaterialCommunityIcons
                            name="account-circle"
                            size={32}
                            color="#2ecc40"
                          />
                        )}
                      </View>
                    ))
                  ) : (
                    <Text style={{ color: '#2ecc40', fontWeight: 'bold' }}>Nenhum usuário online</Text>
                  )}
                </View>
              </View>
              <View style={{ height: 8 }} />
              {/* Grid de botões */}
              <View style={[estilos.grid, { width: width * 0.98, maxWidth: 700 }]}>
                {botoes.map((btn, idx) => (
                  <NeumorphicButton
                    key={btn.titulo}
                    style={[estilos.botao, { width: cardWidth }]}
                    onPress={() => irPara(btn.rota as any)}
                  >
                    <LinearGradient
                      colors={BUTTON_GRADIENT}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 1 }}
                      style={estilos.botaoGradiente}
                    >
                      <View style={estilos.iconeBotao}>
                        {btn.icone}
                        {btn.rota === 'Repertorios' && novaRepertorioCount > 0 && (
                          <Animated.View style={[estilos.badgeWrapper, { opacity: blinkOpacityRep }]}>
                            <View style={estilos.badgeInner}>
                              <Text style={estilos.badgeText}>{novaRepertorioCount > 99 ? '99+' : String(novaRepertorioCount)}</Text>
                            </View>
                            <Text style={estilos.badgeLabel} numberOfLines={1} ellipsizeMode="tail">Novo Repertório</Text>
                          </Animated.View>
                        )}
                        {btn.rota === 'Escalas' && novaEscalaCount > 0 && (
                          <Animated.View style={[estilos.badgeWrapper, { opacity: blinkOpacity }]}>
                            <View style={estilos.badgeInner}>
                              <Text style={estilos.badgeText}>{novaEscalaCount > 99 ? '99+' : String(novaEscalaCount)}</Text>
                            </View>
                            <Text style={estilos.badgeLabel} numberOfLines={1} ellipsizeMode="tail">Nova Escala</Text>
                          </Animated.View>
                        )}
                      </View>
                      <Text style={estilos.textoBotao}>{btn.titulo}</Text>
                    </LinearGradient>
                  </NeumorphicButton>
                ))}
              </View>
            </View>
          </ScrollView>
        </SafeAreaView>
      </LinearGradient>
    </>
  );
}

