import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  StyleSheet,
  Alert,
  ScrollView,
  FlatList,
  TouchableOpacity,
  Linking,
  KeyboardAvoidingView,
  Platform,
  Animated,
  ActivityIndicator,
} from 'react-native';
import { addDoc, collection, getFirestore, doc, updateDoc, setDoc, increment } from 'firebase/firestore';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import { useNavigation } from '@react-navigation/native';
import { MaterialIcons } from '@expo/vector-icons';

const db = getFirestore();

const tonsMaiores = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const tonsMenores = ['Cm', 'C#m', 'Dm', 'D#m', 'Em', 'Fm', 'F#m', 'Gm', 'G#m', 'Am', 'A#m', 'Bm'];

export interface Musica {
  nome: string;
  tom: string;
  linkLetra?: string;
  linkYoutube?: string;
}

// Neumorphic container reutilizável
const NeumorphicContainer = ({ children, style }: any) => (
  <View style={[styles.neumorphicOuter, style]}>
    <View style={styles.neumorphicInner}>{children}</View>
  </View>
);

export default function AdicionarRepertorio(): JSX.Element {
  const navigation = useNavigation();
  const [titulo, setTitulo] = useState('');
  const [data, setData] = useState('');
  const [responsavel, setResponsavel] = useState('');
  const [musicas, setMusicas] = useState<Musica[]>([]);
  const [musicaNome, setMusicaNome] = useState('');
  const [musicaTom, setMusicaTom] = useState('C');
  const [musicaLinkLetra, setMusicaLinkLetra] = useState('');
  const [musicaLinkYoutube, setMusicaLinkYoutube] = useState('');
  const [loading, setLoading] = useState(false);

  // Animação de alto relevo para o botão
  const saveAnim = React.useRef(new Animated.Value(1)).current;

  // Formata a data enquanto digita: 01/06/2024
  function handleDataChange(text: string) {
    let cleaned = text.replace(/\D/g, '');
    let formatted = '';
    if (cleaned.length > 4) {
      formatted = cleaned.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
    } else if (cleaned.length > 2) {
      formatted = cleaned.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
    } else {
      formatted = cleaned;
    }
    setData(formatted);
  }

  const handleAdicionarMusica = () => {
    if (!musicaNome.trim()) {
      Alert.alert('Atenção', 'Informe o nome da música.');
      return;
    }
    setMusicas(prev => [
      ...prev,
      {
        nome: musicaNome,
        tom: musicaTom,
        linkLetra: musicaLinkLetra,
        linkYoutube: musicaLinkYoutube,
      }
    ]);
    setMusicaNome('');
    setMusicaTom('C');
    setMusicaLinkLetra('');
    setMusicaLinkYoutube('');
  };

  const salvarRepertorio = async () => {
    if (!titulo.trim() || !data.trim() || !responsavel.trim() || musicas.length === 0) {
      Alert.alert('Atenção', 'Preencha todos os campos e adicione pelo menos uma música.');
      return;
    }
    setLoading(true);
    try {
      await addDoc(
        collection(db, 'repertorios'),
        {
          titulo,
          data,
          responsavel,
          musicas: musicas.map(m => ({
            nome: m.nome,
            tom: m.tom,
            linkLetra: m.linkLetra,
            linkYoutube: m.linkYoutube,
          })),
          criadoEm: new Date(),
        }
      );
      Alert.alert('Sucesso', 'Repertório criado com sucesso!');
        // incrementa contador remoto (meta/repertorios) e sinal local
        const metaRef = doc(db, 'meta', 'repertorios');
        try {
          await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
        } catch (e) {
          try {
            await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
          } catch (err) {
            console.log('Erro ao atualizar contador remoto de repertorios', err);
          }
        }
        try {
          const cur = await AsyncStorage.getItem('nova_repertorio');
          const num = cur ? parseInt(cur, 10) || 0 : 0;
          const novo = num + 1;
          await AsyncStorage.setItem('nova_repertorio', String(novo));
          await Notifications.setBadgeCountAsync(novo);
        } catch (e) {
          console.log('Não foi possível setar badge/flag local de repertorio', e);
        }
      navigation.goBack();
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível salvar o repertório.');
    } finally {
      setLoading(false);
    }
  };

  // Efeito de alto relevo no botão
  const handlePressIn = () => {
    Animated.spring(saveAnim, {
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };
  const handlePressOut = () => {
    Animated.spring(saveAnim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
  };

  return (
    <View style={styles.bg}>
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
          <View style={styles.headerNeumorphic}>
            <View style={styles.headerRow}>
              {/* Botão Home à esquerda */}
              <TouchableOpacity
                style={styles.headerIconBtn}
                onPress={() => navigation.navigate('Inicio')}
                activeOpacity={0.7}
              >
                <Text style={styles.homeEmoji}>🏠</Text>
              </TouchableOpacity>
              {/* Título centralizado */}
              <Text style={styles.headerTitle}>Adicionar Repertório</Text>
              {/* Botão Voltar à direita */}
              <TouchableOpacity
                style={styles.headerIconBtn}
                onPress={() => navigation.goBack()}
                activeOpacity={0.7}
              >
                <View style={{ alignItems: 'center' }}>
                  <MaterialIcons name="arrow-back" size={24} color="#a084e8" />
                  <Text style={styles.backText}>BACK</Text>
                </View>
              </TouchableOpacity>
            </View>
          </View>

          <NeumorphicContainer style={styles.card}>
            <NeumorphicContainer style={styles.inputGroup}>
              <Text style={styles.label}>Título</Text>
              <TextInput
                style={styles.input}
                value={titulo}
                onChangeText={setTitulo}
                placeholder="Título"
                placeholderTextColor="#90caf9"
              />
            </NeumorphicContainer>
            <NeumorphicContainer style={styles.inputGroup}>
              <Text style={styles.label}>Data</Text>
              <TextInput
                style={styles.input}
                value={data}
                onChangeText={handleDataChange}
                placeholder="Data (ex: 01/06/2024)"
                placeholderTextColor="#90caf9"
                keyboardType="numeric"
                maxLength={10}
              />
            </NeumorphicContainer>
            <NeumorphicContainer style={styles.inputGroup}>
              <Text style={styles.label}>Responsável</Text>
              <TextInput
                style={styles.input}
                value={responsavel}
                onChangeText={setResponsavel}
                placeholder="Responsável"
                placeholderTextColor="#90caf9"
              />
            </NeumorphicContainer>

            <NeumorphicContainer style={styles.section}>
              <Text style={styles.sectionTitle}>Adicionar Música</Text>
              <View style={styles.musicRow}>
                <TextInput
                  style={[styles.input, { flex: 2, marginRight: 8 }]}
                  placeholder="Nome da música"
                  placeholderTextColor="#90caf9"
                  value={musicaNome}
                  onChangeText={setMusicaNome}
                />
              </View>
              <View style={styles.musicRow}>
                <TextInput
                  style={[styles.input, { flex: 2, marginRight: 8 }]}
                  placeholder="Link da letra (opcional)"
                  placeholderTextColor="#90caf9"
                  value={musicaLinkLetra}
                  onChangeText={setMusicaLinkLetra}
                  autoCapitalize="none"
                  autoCorrect={false}
                  keyboardType="url"
                />
              </View>
              <View style={styles.musicRow}>
                <TextInput
                  style={[styles.input, { flex: 2, marginRight: 8 }]}
                  placeholder="Link do YouTube (opcional)"
                  placeholderTextColor="#90caf9"
                  value={musicaLinkYoutube}
                  onChangeText={setMusicaLinkYoutube}
                  autoCapitalize="none"
                  autoCorrect={false}
                  keyboardType="url"
                />
              </View>
              <View style={styles.tonesBlock}>
                <Text style={styles.tonesLabel}>Tons maiores:</Text>
                <FlatList
                  data={tonsMaiores}
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  keyExtractor={item => item}
                  renderItem={({ item }) => (
                    <TouchableOpacity
                      style={[
                        styles.toneButton,
                        musicaTom === item && styles.toneButtonSelected
                      ]}
                      onPress={() => setMusicaTom(item)}
                    >
                      <Text style={[
                        styles.toneButtonText,
                        musicaTom === item && styles.toneButtonTextSelected
                      ]}>{item}</Text>
                    </TouchableOpacity>
                  )}
                />
              </View>
              <View style={styles.tonesBlock}>
                <Text style={styles.tonesLabel}>Tons menores:</Text>
                <FlatList
                  data={tonsMenores}
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  keyExtractor={item => item}
                  renderItem={({ item }) => (
                    <TouchableOpacity
                      style={[
                        styles.toneButton,
                        musicaTom === item && styles.toneButtonSelected
                      ]}
                      onPress={() => setMusicaTom(item)}
                    >
                      <Text style={[
                        styles.toneButtonText,
                        musicaTom === item && styles.toneButtonTextSelected
                      ]}>{item}</Text>
                    </TouchableOpacity>
                  )}
                />
              </View>
              <TouchableOpacity style={styles.addMusicButton} onPress={handleAdicionarMusica}>
                <Text style={styles.addMusicButtonText}>Adicionar Música</Text>
              </TouchableOpacity>
            </NeumorphicContainer>

            <FlatList
              data={musicas}
              keyExtractor={(_, idx) => idx.toString()}
              renderItem={({ item, index }) => (
                <View style={styles.musicListItem}>
                  <Text style={{ flex: 2, color: '#1565c0', fontWeight: 'bold' }}>{item.nome}</Text>
                  <Text style={{ flex: 1, color: '#2196F3', fontWeight: 'bold' }}>{item.tom}</Text>
                  <TouchableOpacity
                    style={[styles.fileButton, { marginLeft: 4 }]}
                    onPress={() => {
                      if (item.linkLetra) {
                        Linking.openURL(item.linkLetra);
                      } else {
                        Alert.alert('Sem link', 'Nenhum link foi adicionado para esta música.');
                      }
                    }}
                  >
                    <Text style={styles.fileButtonText}>
                      {item.linkLetra ? 'Ver Letra' : 'Letra'}
                    </Text>
                  </TouchableOpacity>
                  {item.linkYoutube ? (
                    <TouchableOpacity
                      style={[styles.fileButton, { marginLeft: 8, backgroundColor: '#E53935' }]}
                      onPress={() => Linking.openURL(item.linkYoutube!)}
                    >
                      <Text style={styles.fileButtonText}>YouTube</Text>
                    </TouchableOpacity>
                  ) : null}
                </View>
              )}
              ListHeaderComponent={
                musicas.length > 0 ? (
                  <View style={styles.musicListHeader}>
                    <Text style={{ flex: 2, fontWeight: 'bold', color: '#1565c0' }}>Música</Text>
                    <Text style={{ flex: 1, fontWeight: 'bold', color: '#1565c0' }}>Tom</Text>
                    <Text style={{ flex: 2, fontWeight: 'bold', color: '#1565c0' }}>Letra</Text>
                    <Text style={{ flex: 1, fontWeight: 'bold', color: '#1565c0' }}>YouTube</Text>
                  </View>
                ) : null
              }
            />

            <Animated.View style={{ transform: [{ scale: saveAnim }] }}>
              <TouchableOpacity
                style={styles.saveButton}
                onPress={salvarRepertorio}
                disabled={loading}
                onPressIn={handlePressIn}
                onPressOut={handlePressOut}
                activeOpacity={0.85}
              >
                {loading ? (
                  <ActivityIndicator color="#fff" />
                ) : (
                  <Text style={styles.saveButtonText}>Salvar Repertório</Text>
                )}
              </TouchableOpacity>
            </Animated.View>
            <TouchableOpacity style={styles.cancelButton} onPress={() => navigation.goBack()}>
              <Text style={styles.cancelButtonText}>Cancelar</Text>
            </TouchableOpacity>
          </NeumorphicContainer>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

